--- Process transport for `fstar.exe --ide`.
---
--- Owns the child process, writes newline-delimited JSON queries, reads
--- newline-delimited JSON messages, and routes them to per-query handlers.
--- F* answers a query with id "N" using messages whose ids are "N" or "N.k"
--- (sub-queries generated by `full-buffer`); all of them go to the handler
--- registered for "N".
---
--- Positions are converted in exactly one place (`M.to_buf_pos` /
--- `M.to_fstar_pos`): F* lines are 1-based, columns are 0-based counts of
--- characters (Unicode code points), not bytes.

local M = {}

---@class neostar.Handlers
---@field on_message? fun(msg: table)   every message routed to this query
---@field on_response? fun(status: string, response: any, msg: table)  response whose id equals the query id
---@field persistent? boolean  keep routing after the response (full-buffer runs end with a progress message, not a response)

---@class neostar.Transport
---@field cmd string[]
---@field cwd string
---@field proc? vim.SystemObj
---@field handlers table<string, neostar.Handlers>
---@field stderr string[]
---@field greeting? table
local Transport = {}
Transport.__index = Transport

--- Convert an F* `[line, col]` pair to a 0-based buffer (row, byte col).
--- Without `line_text` the column is returned in characters.
---@param pos integer[]
---@param line_text? string text of that line, to convert characters to bytes
---@return integer row, integer col
function M.to_buf_pos(pos, line_text)
  local row = math.max((pos[1] or 1) - 1, 0)
  local col = math.max(pos[2] or 0, 0)
  if line_text then
    local nchars = vim.str_utfindex(line_text, "utf-32")
    if col >= nchars then
      col = #line_text
    else
      col = vim.str_byteindex(line_text, "utf-32", col, false)
    end
  end
  return row, col
end

--- Convert a 0-based buffer (row, byte col) to F* (line, character column).
---@param line_text? string text of that line, to convert bytes to characters
---@return integer line, integer column
function M.to_fstar_pos(row, col, line_text)
  if line_text then
    col = vim.str_utfindex(line_text, "utf-32", math.min(col, #line_text), false)
  end
  return row + 1, col
end

--- Root of a query id: "12.3" -> "12".
---@param qid any
---@return string?
function M.root_qid(qid)
  if type(qid) ~= "string" then
    return nil
  end
  return qid:match("^([^%.]+)")
end

---@param opts {cmd: string[], cwd?: string, on_unrouted?: fun(msg: table), on_exit?: fun(code: integer, stderr: string), spawn?: fun(cmd: string[], o: table, on_exit: fun(out: vim.SystemCompleted)): vim.SystemObj}
---@return neostar.Transport
function M.new(opts)
  local self = setmetatable({
    cmd = opts.cmd,
    cwd = opts.cwd,
    on_unrouted = opts.on_unrouted or function() end,
    on_exit = opts.on_exit or function() end,
    spawn = opts.spawn or vim.system,
    handlers = {},
    stderr = {},
    next_id = 0,
    partial = "",
    closing = false,
    exited = false,
  }, Transport)
  return self
end

---@return boolean ok, string? err
function Transport:start()
  local ok, proc = pcall(self.spawn, self.cmd, {
    cwd = self.cwd,
    stdin = true,
    text = true,
    stdout = function(err, data)
      if data then
        vim.schedule(function()
          self:_on_stdout(data)
        end)
      end
    end,
    stderr = function(_, data)
      if data then
        table.insert(self.stderr, data)
      end
    end,
  }, function(out)
    vim.schedule(function()
      self.exited = true
      if not self.closing then
        self.on_exit(out.code, self:stderr_text())
      end
    end)
  end)
  if not ok then
    return false, tostring(proc)
  end
  self.proc = proc
  return true
end

function Transport:stderr_text()
  local s = table.concat(self.stderr)
  if #s > 4000 then
    s = s:sub(-4000)
  end
  return s
end

function Transport:_on_stdout(data)
  local buf = self.partial .. data
  local start = 1
  while true do
    local nl = buf:find("\n", start, true)
    if not nl then
      break
    end
    local line = buf:sub(start, nl - 1)
    start = nl + 1
    if line:match("%S") then
      self:_on_line(line)
    end
  end
  self.partial = buf:sub(start)
end

function Transport:_on_line(line)
  local ok, msg = pcall(vim.json.decode, line, { luanil = { object = true, array = true } })
  if not ok or type(msg) ~= "table" then
    return
  end
  self:dispatch(msg)
end

--- Route one decoded message. Public so tests can inject messages.
---@param msg table
function Transport:dispatch(msg)
  if msg.kind == "protocol-info" then
    self.greeting = msg
    return
  end
  local root = M.root_qid(msg["query-id"])
  local h = root and self.handlers[root]
  if not h then
    self.on_unrouted(msg)
    return
  end
  if h.on_message then
    h.on_message(msg)
  end
  if msg.kind == "response" and msg["query-id"] == root then
    if not h.persistent then
      self.handlers[root] = nil
    end
    if h.on_response then
      h.on_response(msg.status, msg.response, msg)
    end
  end
end

--- Send a query. Returns the query id used.
---@param query string
---@param args table
---@param handlers? neostar.Handlers
---@return string? qid, string? err
function Transport:request(query, args, handlers)
  if not self.proc or self.exited then
    return nil, "F* process is not running"
  end
  self.next_id = self.next_id + 1
  local qid = tostring(self.next_id)
  if handlers then
    self.handlers[qid] = handlers
  end
  local payload = vim.json.encode({ ["query-id"] = qid, query = query, args = args or vim.empty_dict() })
  local ok, err = pcall(self.proc.write, self.proc, payload .. "\n")
  if not ok then
    self.handlers[qid] = nil
    return nil, tostring(err)
  end
  return qid
end

--- Forget the handler of a query (its later messages become unrouted).
function Transport:forget(qid)
  self.handlers[qid] = nil
end

function Transport:is_running()
  return self.proc ~= nil and not self.exited
end

function Transport:stop()
  self.closing = true
  self.handlers = {}
  if self.proc and not self.exited then
    pcall(self.proc.kill, self.proc, 9)
  end
end

M.Transport = Transport
return M
